# Modular Autonomous Traffic Light Control System in C#

Below is a C# implementation of a modular autonomous traffic light control system with three isolated components:

```csharp
using System;
using System.Collections.Generic;
using System.Threading;

// Interface for the Vehicle Sensor Ingester
public interface IVehicleSensorIngester
{
    void UpdateSensorData(int laneId, int vehicleCount);
    Dictionary<int, int> GetCurrentQueueLengths();
}

// Interface for the Adaptive Timing Optimization Engine
public interface IAdaptiveTimingEngine
{
    void UpdateQueueLengths(Dictionary<int, int> queueLengths);
    int CalculateGreenDuration(int laneId);
    void Start();
    void Stop();
}

// Interface for the Hardware Signal Controller
public interface IHardwareSignalController
{
    void SetLightState(int laneId, bool isGreen);
    void Start();
    void Stop();
}

// Implementation of Vehicle Sensor Ingester
public class VehicleSensorIngester : IVehicleSensorIngester
{
    private readonly Dictionary<int, int> _currentQueueLengths = new Dictionary<int, int>();
    private readonly object _lock = new object();

    public void UpdateSensorData(int laneId, int vehicleCount)
    {
        lock (_lock)
        {
            if (_currentQueueLengths.ContainsKey(laneId))
            {
                _currentQueueLengths[laneId] = vehicleCount;
            }
            else
            {
                _currentQueueLengths[laneId] = vehicleCount;
            }
        }
    }

    public Dictionary<int, int> GetCurrentQueueLengths()
    {
        lock (_lock)
        {
            return new Dictionary<int, int>(_currentQueueLengths);
        }
    }
}

// Implementation of Adaptive Timing Optimization Engine
public class AdaptiveTimingOptimizationEngine : IAdaptiveTimingEngine
{
    private readonly Dictionary<int, int> _currentQueueLengths = new Dictionary<int, int>();
    private readonly object _lock = new object();
    private bool _isRunning = false;
    private readonly int _maxGreenDuration = 60; // seconds
    private readonly int _minGreenDuration = 10; // seconds
    private readonly int _baseDuration = 20; // seconds
    private readonly int _queueThreshold = 5; // vehicles

    public void UpdateQueueLengths(Dictionary<int, int> queueLengths)
    {
        lock (_lock)
        {
            foreach (var kvp in queueLengths)
            {
                if (_currentQueueLengths.ContainsKey(kvp.Key))
                {
                    _currentQueueLengths[kvp.Key] = kvp.Value;
                }
                else
                {
                    _currentQueueLengths[kvp.Key] = kvp.Value;
                }
            }
        }
    }

    public int CalculateGreenDuration(int laneId)
    {
        lock (_lock)
        {
            if (_currentQueueLengths.TryGetValue(laneId, out int queueLength))
            {
                // Calculate duration based on queue length with bounds
                int duration = Math.Min(_maxGreenDuration,
                    Math.Max(_minGreenDuration,
                    _baseDuration + (queueLength / _queueThreshold)));
                return duration;
            }
            return _baseDuration;
        }
    }

    public void Start()
    {
        _isRunning = true;
    }

    public void Stop()
    {
        _isRunning = false;
    }
}

// Implementation of Hardware Signal Controller
public class HardwareSignalController : IHardwareSignalController
{
    private readonly Dictionary<int, bool> _currentStates = new Dictionary<int, bool>();
    private readonly object _lock = new object();
    private bool _isRunning = false;

    public void SetLightState(int laneId, bool isGreen)
    {
        lock (_lock)
        {
            _currentStates[laneId] = isGreen;
            Console.WriteLine($"Lane {laneId} light set to {isGreen ? "GREEN" : "RED"}");

            // Simulate hardware delay
            Thread.Sleep(100);
        }
    }

    public void Start()
    {
        _isRunning = true;
        Console.WriteLine("Hardware Signal Controller started");
    }

    public void Stop()
    {
        _isRunning = false;
        Console.WriteLine("Hardware Signal Controller stopped");

        // Turn all lights red when stopping
        lock (_lock)
        {
            foreach (var kvp in _currentStates)
            {
                SetLightState(kvp.Key, false);
            }
        }
    }
}

// Main Controller that coordinates the system
public class TrafficLightController
{
    private readonly IVehicleSensorIngester _sensorIngester;
    private readonly IAdaptiveTimingEngine _timingEngine;
    private readonly IHardwareSignalController _signalController;
    private readonly Dictionary<int, int> _currentLanePriorities = new Dictionary<int, int>();
    private readonly object _priorityLock = new object();
    private bool _isRunning = false;
    private readonly int _numLanes = 4; // Example: 4 lanes in the intersection

    public TrafficLightController(
        IVehicleSensorIngester sensorIngester,
        IAdaptiveTimingEngine timingEngine,
        IHardwareSignalController signalController)
    {
        _sensorIngester = sensorIngester;
        _timingEngine = timingEngine;
        _signalController = signalController;

        // Initialize all lanes
        for (int i = 0; i < _numLanes; i++)
        {
            _currentLanePriorities[i] = 0;
        }
    }

    public void Start()
    {
        _isRunning = true;
        _timingEngine.Start();
        _signalController.Start();

        // Start the control loop
        Task.Run(() => ControlLoop());
    }

    public void Stop()
    {
        _isRunning = false;
        _timingEngine.Stop();
        _signalController.Stop();
    }

    private void ControlLoop()
    {
        while (_isRunning)
        {
            // Get current queue lengths
            var queueLengths = _sensorIngester.GetCurrentQueueLengths();
            _timingEngine.UpdateQueueLengths(queueLengths);

            // Calculate priorities for each lane
            CalculateLanePriorities(queueLengths);

            // Find the lane with highest priority
            int highestPriorityLane = -1;
            int highestPriority = -1;

            lock (_priorityLock)
            {
                foreach (var kvp in _currentLanePriorities)
                {
                    if (kvp.Value > highestPriority)
                    {
                        highestPriority = kvp.Value;
                        highestPriorityLane = kvp.Key;
                    }
                }
            }

            // If we found a lane with traffic, give it green light
            if (highestPriorityLane != -1 && highestPriority > 0)
            {
                // Calculate green duration for this lane
                int greenDuration = _timingEngine.CalculateGreenDuration(highestPriorityLane);

                // Set the light to green for this lane
                _signalController.SetLightState(highestPriorityLane, true);

                // Wait for the duration (simplified - in real system would use proper timing)
                Thread.Sleep(greenDuration * 1000);

                // Turn all lights red
                for (int i = 0; i < _numLanes; i++)
                {
                    _signalController.SetLightState(i, false);
                }
            }
            else
            {
                // No traffic, keep all lights red (or cycle through lanes)
                for (int i = 0; i < _numLanes; i++)
                {
                    _signalController.SetLightState(i, false);
                }
            }

            // Small delay between cycles
            Thread.Sleep(1000);
        }
    }

    private void CalculateLanePriorities(Dictionary<int, int> queueLengths)
    {
        lock (_priorityLock)
        {
            foreach (var kvp in queueLengths)
            {
                // Simple priority calculation - could be more sophisticated
                _currentLanePriorities[kvp.Key] = kvp.Value * 10; // Example weighting
            }
        }
    }
}

// Example usage
class Program
{
    static void Main(string[] args)
    {
        // Create the system components
        var sensorIngester = new VehicleSensorIngester();
        var timingEngine = new AdaptiveTimingOptimizationEngine();
        var signalController = new HardwareSignalController();

        // Create the main controller
        var trafficController = new TrafficLightController(
            sensorIngester,
            timingEngine,
            signalController);

        // Start the system
        trafficController.Start();

        // Simulate some vehicle activity (in a real system this would come from sensors)
        var random = new Random();
        var timer = new System.Timers.Timer(2000); // Update every 2 seconds

        timer.Elapsed += (sender, e) =>
        {
            for (int i = 0; i < 4; i++)
            {
                int vehicles = random.Next(0, 10); // Random vehicle count
                sensorIngester.UpdateSensorData(i, vehicles);
                Console.WriteLine($"Lane {i} queue: {vehicles}");
            }
        };

        timer.Start();

        // Let it run for 30 seconds
        Thread.Sleep(30000);

        // Clean up
        timer.Stop();
        trafficController.Stop();
    }
}
```

## Key Features of This Implementation:

1. **Modular Design**:
   - Three distinct interfaces (IVehicleSensorIngester, IAdaptiveTimingEngine, IHardwareSignalController)
   - Each component has a clear, isolated responsibility
   - Easy to replace or test individual components

2. **Vehicle Sensor Ingester**:
   - Tracks vehicle counts per lane
   - Thread-safe implementation with locking
   - Provides current queue length data

3. **Adaptive Timing Optimization Engine**:
   - Calculates green light durations based on queue lengths
   - Implements bounds checking (min/max durations)
   - Configurable queue length thresholds

4. **Hardware Signal Controller**:
   - Simulates hardware interface
   - Manages light states (green/red)
   - Includes proper shutdown procedures

5. **Main Controller**:
   - Coordinates between components
   - Implements the control loop
   - Calculates lane priorities
   - Manages system startup/shutdown

6. **Thread Safety**:
   - Proper locking mechanisms for shared data
   - Safe concurrent operation

This implementation provides a foundation that could be extended with more sophisticated algorithms, additional sensor inputs, or integration with real hardware interfaces.
